 static Frame DFrame(double t,double start,double distance,int laps=0,double last=-1){var f=new Frame{Connected=true,HasTelemetry=true,InRealtime=true,Track="Spa",TrackLength=1000,Elapsed=t,Session=1,SessionStarted=1,PlayerId=1,PlayerName="Arthur",PlayerClass="LMGT3"};f.Drivers.Add(new Driver{Id=1,Name="Arthur",Class="LMGT3",CarName="Porsche 911 GT3 R",VehicleKey="911",IsPlayer=true,Control=1,CountLapFlag=2,LapStart=start,LapDistance=distance,Laps=laps,LastLap=last,Speed=36});return f;}
 static DeltaLap Reference(DeltaProfile p,double time=100){return new DeltaLap{Profile=p,Time=time,Points=new[]{new DeltaPoint{Distance=0,Time=0},new DeltaPoint{Distance=p.Length/2,Time=time/2},new DeltaPoint{Distance=p.Length,Time=time}}};}
 static Frame DriveLap(DeltaTracker delta,double start,double duration,int laps,bool invalid=false){for(double t=0;t<duration;t+=.25){var f=DFrame(start+t,start,t/duration*1000,laps);f.LapInvalid=invalid&&t>duration/2;delta.Apply(f);}var end=DFrame(start+duration,start+duration,0,laps+1,duration);delta.Apply(end);return end;}
